<script setup lang="ts">
import {bodyTree,type BodyNode} from '../writing/body'
import {confirmAction} from '../ui/confirm'
import ModuleHeading from '../writing/ModuleHeading.vue'
import {newId} from '../ids'
import {ref,computed} from 'vue'
import { type Life } from './types'
import type { Connections } from '../admin/archive'
import ActivityMediaPicker from './ActivityMediaPicker.vue'
import ItineraryExtract from './ItineraryExtract.vue'
import PrivatePreview from '../admin/PrivatePreview.vue'
const props=defineProps<{generation?:{status:string;message?:string};panel?:'media'|'itinerary';simple?:boolean;travel?:boolean;value:Life;connections:Connections;disabled:boolean;recordId?:string;revision?:number;body?:string;unsaved?:boolean;dateFields?:{id:string;name:string;value:string}[]}>()
const emit=defineEmits<{(e:'pending',value:boolean):void;(e:'synchronized',record:any):void}>()
const generationLabels:Record<string,string>={not_generated:'未生成',generated:'已生成',body_updated:'正文已更新',needs_review:'需要校对',failed:'提取失败'}
const photoList=computed(()=>[...props.connections.media].sort((a,b)=>{const day=(id:string)=>props.value.photos.find(p=>p.media_id===id)?.taken_on||'9999';return day(a.id).localeCompare(day(b.id))||a.id.localeCompare(b.id)}))
const traffic=computed(()=>{const walk=(nodes:BodyNode[]):any[]=>nodes.flatMap(n=>n.entry?.kind==='t'?[n.entry]:n.children?walk(n.children):[]);return walk(bodyTree(props.body||'',2))})
const openedActivity=ref('')
const batchDay=ref(''),photoNotice=ref('')
function batchDates(){if(!batchDay.value)return;let count=0;for(const m of props.connections.media){if(!props.value.photos.some(p=>p.media_id===m.id)&&props.value.photos.length>=100)break;const n=note(m.id);if(!n.taken_on){n.taken_on=batchDay.value;count++}}photoNotice.value='已为 '+count+' 张未知日期照片设置日期，已有日期未更改；保存后生效。'}
const adoptStart=ref(''),adoptEnd=ref(''),dateNotice=ref('')
async function adoptDates(){const start=props.dateFields?.find(f=>f.id===adoptStart.value)?.value,end=props.dateFields?.find(f=>f.id===adoptEnd.value)?.value;if(!start&&!end)return;const from=start||props.value.start_date,to=end||props.value.end_date;if(from&&to&&from>to){dateNotice.value='开始日期不能晚于结束日期';return}if(!await confirmAction('把所选动态日期字段复制到旅行起止日期？不会修改原字段，保存后才生效。'))return;if(start)props.value.start_date=start;if(end)props.value.end_date=end;dateNotice.value='已采用所选日期，请保存文章。'}
function add(){const id=newId();openedActivity.value=id;props.value.activities.push({kind:'other',dish:'',price:null,currency:'',rating:null,experience:'',source_key:null,id,day:props.value.start_date||new Date().toISOString().slice(0,10),time:null,title:'',description:'',place_id:null,media_ids:[]})}
function move(i:number,d:number){const row=props.value.activities.splice(i,1)[0]!;props.value.activities.splice(i+d,0,row)}
function note(id:string){let n=props.value.photos.find(p=>p.media_id===id);if(!n){if(props.value.photos.length>=100){photoNotice.value='单篇最多100项照片注记，其他正文图片仍保留；请先清除不需要的注记。';return {media_id:id,taken_on:null,place_id:null,group_name:''}}n={media_id:id,taken_on:null,place_id:null,group_name:''};props.value.photos.push(n)}return n}
</script>
<template><section class="life-editor"><ModuleHeading v-if="panel" :kind="panel" :title="panel==='itinerary'?'旅行行程':'图片与媒体'" :description="panel==='itinerary'?'按日期整理旅程，保留每一次手动维护的记忆。':'整理照片日期、地点与分组，原图与引用保持独立。'"/><h3 v-if="!panel" v-show="panel!=='itinerary'">图片及照片日期整理</h3><p v-show="panel!=='itinerary'" class="muted">图片可在正文附近直接上传；新图片保存后读取 EXIF 拍摄日期，未知日期可批量设置。不会用上传日期替代拍摄日期。</p><details v-show="panel!=='media'" :open="panel==='itinerary'" v-if="travel!==false&&(!simple||travel)"><summary>行程整理与历史手动活动</summary><div v-if="!simple" class="editor-meta"><label>旅行开始日期<input v-model="value.start_date" type="date" :disabled="disabled" /></label><label>旅行结束日期<input v-model="value.end_date" type="date" :disabled="disabled" /></label></div><details v-if="!simple&&dateFields?.length"><summary>采用已有日期字段（免重复输入）</summary><label>开始日期来源<select aria-label="开始日期来源" v-model="adoptStart" :disabled="disabled"><option value="">保留当前开始日期</option><option v-for="f in dateFields" :key="f.id" :value="f.id">{{f.name}} · {{f.value}}</option></select></label><label>结束日期来源<select aria-label="结束日期来源" v-model="adoptEnd" :disabled="disabled"><option value="">保留当前结束日期</option><option v-for="f in dateFields" :key="f.id" :value="f.id">{{f.name}} · {{f.value}}</option></select></label><button type="button" class="quiet" :disabled="disabled||(!adoptStart&&!adoptEnd)" @click="adoptDates">采用所选日期</button><p role="status">{{dateNotice}}</p></details><label>地图展示方式<select v-model="value.map_mode" aria-label="地图展示方式" :disabled="disabled"><option value="offline">离线地点示意图（无第三方请求）</option><option value="hidden">关闭地图，仅显示地点列表</option></select></label><p class="muted">结构化起止日期用于行程范围校验；自定义日期字段保持独立，不会自动覆盖。草稿可暂缺起止日期，发布有行程的记录前需填写出发日期，返回日期可为空。</p>
<p v-if="generation" role="status">行程整理：{{generationLabels[generation.status]||'未生成'}}<span v-if="generation.message"> · {{generation.message}}</span></p><ItineraryExtract @pending="emit('pending',$event)" @synchronized="emit('synchronized',$event)" :record-id="recordId" :revision="revision" :body="body" :value="value" :disabled="disabled||!!unsaved"/><template v-for="(a,i) in value.activities" :key="a.id"><h4 v-if="i===0||value.activities[i-1]?.day!==a.day" class="activity-day">{{a.day}}</h4><details class="field-config activity-config" :open="openedActivity===a.id"><summary>{{a.time||'时间未定'}} · {{a.title||'新活动'}} · {{a.media_ids.length}} 张照片</summary><div class="actions"><strong>活动 {{i+1}}</strong><button type="button" class="quiet" :disabled="disabled||i===0" @click="move(i,-1)">活动上移</button><button type="button" class="quiet" :disabled="disabled||i===value.activities.length-1" @click="move(i,1)">活动下移</button><button type="button" class="quiet" :disabled="disabled" @click="value.activities.splice(i,1)">移除活动（保留历史）</button></div><div class="editor-meta"><label>活动日期<input v-model="a.day" type="date" required :disabled="disabled" /></label><label>活动时间（可留空）<input v-model="a.time" type="time" :disabled="disabled" /></label></div><label>引用本文章交通卡片<select v-model="a.experience_id" :disabled="disabled"><option :value="null">不引用</option><option v-for="e in traffic" :key="e.id" :value="e.id">{{e.name}}</option></select></label><label>活动类型<select v-model="a.kind" aria-label="活动类型" :disabled="disabled"><option value="other">其他</option><option value="food">美食</option><option value="sight">景点</option><option value="transport">交通</option></select></label><template v-if="a.kind==='food'"><label>菜品<input v-model="a.dish" maxlength="200" :disabled="disabled"/></label><div class="editor-meta"><label>价格<input v-model="a.price" type="number" min="0" step="0.01" :disabled="disabled"/></label><label>币种（如CNY）<input v-model="a.currency" maxlength="3" pattern="[A-Z]{3}|" :disabled="disabled"/></label><label>评分（0–5，可留空）<select aria-label="评分（0–5，可留空）" v-model="a.rating" :disabled="disabled"><option :value="null">未评分</option><option v-for="n in [0,1,2,3,4,5]" :key="n" :value="n">{{n}}</option></select></label></div><label>用餐感受<textarea v-model="a.experience" maxlength="10000" rows="3" :disabled="disabled"/></label></template><label>活动标题<input v-model="a.title" maxlength="200" required :disabled="disabled" /></label><label>活动说明<textarea v-model="a.description" rows="3" maxlength="10000" :disabled="disabled" /></label><label>活动地点<select v-model="a.place_id" aria-label="活动地点" :disabled="disabled"><option :value="null">未指定地点</option><option v-for="p in connections.places" :key="p.id" :value="p.id">{{p.name}}{{p.active?'':'（停用，历史保留）'}}</option></select></label><ActivityMediaPicker v-model="a.media_ids" :media="connections.media" :disabled="disabled"/></details></template><button type="button" class="quiet" :disabled="disabled||value.activities.length>=300" @click="add">添加行程活动</button></details>
<details v-show="panel!=='itinerary'" :open="simple"><summary>编辑照片日期、地点与分组</summary><div class="actions"><label>未知日期照片批量设置<input v-model="batchDay" type="date" :disabled="disabled"/></label><button type="button" :disabled="disabled||!batchDay" @click="batchDates">仅填充未知日期</button><p role="status">{{photoNotice}}</p></div><p class="muted">顺序、封面与说明沿用上方图片设置；这里增加记录级日期、地点和手工分组，不复制文件。模板中可选择按日期、地点或手工分组展示。</p><section v-for="m in photoList" :key="m.id" class="photo-note"><PrivatePreview :id="m.id" :alt="m.asset.alt" /><div><strong>{{m.asset.title||m.asset.filename}}</strong><p>拍摄日期：{{value.photos.find(p=>p.media_id===m.id)?.taken_on||'未知（可手动选择）'}}</p><label>照片日期<input :value="value.photos.find(p=>p.media_id===m.id)?.taken_on||''" type="date" :disabled="disabled" @input="note(m.id).taken_on=($event.target as HTMLInputElement).value||null" /></label><label>照片地点<select :value="value.photos.find(p=>p.media_id===m.id)?.place_id||''" aria-label="照片地点" :disabled="disabled" @change="note(m.id).place_id=($event.target as HTMLSelectElement).value||null"><option value="">未指定地点</option><option v-for="p in connections.places" :key="p.id" :value="p.id">{{p.name}}</option></select></label><button v-if="value.photos.some(p=>p.media_id===m.id)" type="button" class="quiet" :disabled="disabled" @click="value.photos=value.photos.filter(p=>p.media_id!==m.id)">清除此照片注记（保留原图）</button><label>照片分组<input :value="value.photos.find(p=>p.media_id===m.id)?.group_name||''" maxlength="100" :disabled="disabled" @input="note(m.id).group_name=($event.target as HTMLInputElement).value" /></label></div></section></details></section></template>
<style scoped>
.life-editor{margin-top:30px;border-top:1px solid var(--line);padding-top:20px}.life-editor summary{padding:14px 0;min-height:44px;cursor:pointer}.photo-note{display:grid;grid-template-columns:110px minmax(0,1fr);gap:18px;border-top:1px solid var(--line);padding:18px 0}.photo-note img{width:110px;border-radius:var(--ui-radius)}.life-editor input[type=checkbox]{width:auto}.life-editor strong{overflow-wrap:anywhere}@media(max-width:600px){.photo-note{grid-template-columns:1fr}.photo-note img{width:100%;max-height:180px;object-fit:contain}}
</style>
